  function uploadByteDetail(loaded,total){return pickText("已发送 "+formatBytes(loaded)+" / 一共 "+formatBytes(total),"Sent "+formatBytes(loaded)+" / Total "+formatBytes(total),"送信済み "+formatBytes(loaded)+" / 合計 "+formatBytes(total),"已傳送 "+formatBytes(loaded)+" / 總計 "+formatBytes(total))}
  function conversionProgress(kind,file,progress){var phase=String(progress&&progress.phase||"");var current=Math.max(0,Number(progress&&progress.current||0));var total=Math.max(0,Number(progress&&progress.total||0));var percent=total>0?Math.min(100,Math.round(current*100/total)):0;var label;if(kind==="gif"){label=phase==="encode"?pickText("正在压缩 GIF","Compressing GIF","GIF を圧縮中","正在壓縮 GIF"):pickText("正在解析 GIF","Reading GIF","GIF を解析中","正在解析 GIF")}else{label=phase==="mux"?pickText("正在封装 MJPEG AVI","Building MJPEG AVI","MJPEG AVI を作成中","正在封裝 MJPEG AVI"):phase.indexOf("audio")===0?pickText("正在转换音轨","Converting audio","音声を変換中","正在轉換音軌"):pickText("正在转换视频帧","Converting video frames","動画フレームを変換中","正在轉換影片影格")}var detail=total>0?current+" / "+total:pickText("正在准备转换…","Preparing conversion…","変換を準備中…","正在準備轉換…");q("#mediaSyncStatus").textContent=label+" · "+file.name+(total>0?" · "+percent+"%":"");setMediaOperationProgress(label+" · "+file.name,current,total,detail)}
