  function mediaPart(entry,part){if(entry.kind!=="music"){return {path:entry.path,name:entry.name}}if(part==="lyric"){return {path:entry.lyricPath,name:entry.lyricName}}return {path:entry.audioPath,name:entry.audioName}}
